     1→import { Block, Text } from "@prototyp/skeletor";
     2→import { useIsFocused } from "@react-navigation/native";
     3→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     4→import {
     5→  MembershipState_Tags,
     6→  type RoomMember,
     7→} from "@unomed/react-native-matrix-sdk";
     8→import { MatrixService } from "modules/matrix-client/services";
     9→import { NavigationContainerRef } from "modules/navigation/const";
    10→import { useCallback, useEffect, useMemo, useState } from "react";
    11→import { Image, SectionList, StyleSheet } from "react-native";
    12→import { Button, Loading, MemberDetailsBottomSheet } from "shared/components";
    13→import { GoBackHeader } from "shared/components/go-back-header/GoBackHeader";
    14→import { ScreenLayout } from "shared/components/screen-layout/ScreenLayout";
    15→import { UserImage } from "shared/components/user-image/UserImage";
    16→import { useMemberDetails } from "shared/hooks";
    17→import { Colors, TextSize } from "shared/styles";
    18→
    19→export const RoomMembers: React.FC<
    20→  NativeStackScreenProps<Routes, "roomMembers">
    21→> = ({ route }) => {
    22→  const { members: initialMembers, roomId } = route.params;
    23→  const [members, setMembers] = useState<RoomMember[]>(initialMembers);
    24→  const [isRefreshing, setIsRefreshing] = useState(false);
    25→  const isFocused = useIsFocused();
    26→  const {
    27→    selectedMember,
    28→    isBottomSheetOpen,
    29→    openMemberDetails,
    30→    closeMemberDetails,
    31→  } = useMemberDetails();
    32→
    33→  const pendingMembers = useMemo(
    34→    () =>
    35→      members.filter(
    36→        (member) => member.membership?.tag === MembershipState_Tags.Invite,
    37→      ),
    38→    [members],
    39→  );
    40→  const acceptedMembers = useMemo(
    41→    () =>
    42→      members.filter(
    43→        (member) => member.membership?.tag === MembershipState_Tags.Join,
    44→      ),
    45→    [members],
    46→  );
    47→  const bannedMembers = useMemo(
    48→    () =>
    49→      members.filter(
    50→        (member) => member.membership?.tag === MembershipState_Tags.Ban,
    51→      ),
    52→    [members],
    53→  );
    54→
    55→  const sections = useMemo(
    56→    () => [
    57→      {
    58→        title: "Pending",
    59→        data: pendingMembers,
    60→      },
    61→      {
    62→        title: "",
    63→        data: acceptedMembers,
    64→      },
    65→      {
    66→        title: "Banned",
    67→        data: bannedMembers,
    68→      },
    69→    ],
    70→    [pendingMembers, acceptedMembers, bannedMembers],
    71→  );
    72→
    73→  const refreshMembers = useCallback(async () => {
    74→    setIsRefreshing(true);
    75→    try {
    76→      const room = MatrixService.getRoomInfo(roomId);
    77→      if (!room) return;
    78→
    79→      const membersInfo = await room.members();
    80→      const membersList = membersInfo.nextChunk(100000) ?? [];
    81→      setMembers(membersList);
    82→    } catch (error) {
    83→      console.error("Failed to refresh members:", error);
    84→    } finally {
    85→      setIsRefreshing(false);
    86→    }
    87→  }, [roomId]);
    88→
    89→  const handleMemberAction = useCallback(
    90→    (userId: string, action: "remove" | "ban" | "unban") => {
    91→      setMembers((currentMembers) => {
    92→        return currentMembers.map((member) => {
    93→          if (member.userId !== userId) return member;
    94→
    95→          const newMembershipTag =
    96→            action === "ban"
    97→              ? MembershipState_Tags.Ban
    98→              : MembershipState_Tags.Leave; // For unban and remove, we change the membership to leave
    99→
   100→          return {
   101→            ...member,
   102→            membership: {
   103→              ...member.membership,
   104→              tag: newMembershipTag,
   105→            },
   106→          };
   107→        });
   108→      });
   109→
   110→      setTimeout(() => {
   111→        refreshMembers();
   112→      }, 2000);
   113→    },
   114→    [refreshMembers],
   115→  );
   116→
   117→  const handleMemberPress = useCallback(
   118→    (member: RoomMember) => {
   119→      openMemberDetails({
   120→        userId: member.userId,
   121→        displayName: member.displayName ?? "Unknown",
   122→        avatarUrl: member.avatarUrl ?? null,
   123→        membershipTag: member.membership?.tag,
   124→      });
   125→    },
   126→    [openMemberDetails],
   127→  );
   128→
   129→  useEffect(() => {
   130→    if (!isFocused) return;
   131→    refreshMembers();
   132→  }, [isFocused, refreshMembers]);
   133→
   134→  return (
   135→    <ScreenLayout type="modal">
   136→      {isRefreshing && <Loading text="Refreshing members..." />}
   137→      <Block align="center" width="100%">
   138→        <GoBackHeader
   139→          title="Members"
   140→          margins={0}
   141→          rightComp={
   142→            <Button.Wrapper
   143→              onPress={() =>
   144→                NavigationContainerRef.navigate("invitePeople", {
   145→                  roomId,
   146→                  members,
   147→                })
   148→              }
   149→            >
   150→              <Image
   151→                source={require("assets/icons/plus.png")}
   152→                tintColor={Colors.white}
   153→                width={24}
   154→                height={24}
   155→              />
   156→            </Button.Wrapper>
   157→          }
   158→        />
   159→        <Text size={TextSize.tiny} color={Colors.white80}>
   160→          {acceptedMembers.length}{" "}
   161→          {acceptedMembers.length === 1 ? "member" : " members"}
   162→        </Text>
   163→        <SectionList
   164→          sections={sections}
   165→          style={styles.container}
   166→          contentContainerStyle={styles.contentContainer}
   167→          renderItem={({ item }) => (
   168→            <Button.Wrapper onPress={() => handleMemberPress(item)}>
   169→              <Block flexDirection="row" align="center" gap={12} width="100%">
   170→                <UserImage
   171→                  avatarUrl={item.avatarUrl}
   172→                  displayName={item.displayName}
   173→                  width={40}
   174→                  height={40}
   175→                />
   176→                <Text>{item.displayName}</Text>
   177→              </Block>
   178→            </Button.Wrapper>
   179→          )}
   180→          renderSectionHeader={({ section }) => {
   181→            if (!section.data.length) return null;
   182→
   183→            return (
   184→              <Block>
   185→                <Text size={TextSize.tiny} color={Colors.white80}>
   186→                  {section.title === ""
   187→                    ? `${section.data.length} ${section.data.length === 1 ? "member" : "members"}`
   188→                    : section.title}
   189→                </Text>
   190→              </Block>
   191→            );
   192→          }}
   193→        />
   194→      </Block>
   195→      <MemberDetailsBottomSheet
   196→        isBottomSheetOpen={isBottomSheetOpen}
   197→        selectedMember={selectedMember}
   198→        roomId={roomId}
   199→        onClose={closeMemberDetails}
   200→        onMemberAction={handleMemberAction}
   201→      />
   202→    </ScreenLayout>
   203→  );
   204→};
   205→
   206→const styles = StyleSheet.create({
   207→  container: {
   208→    width: "100%",
   209→    gap: 12,
   210→    marginTop: 36,
   211→    padding: 0,
   212→  },
   213→  contentContainer: {
   214→    width: "100%",
   215→    gap: 12,
   216→  },
   217→});
   218→

