    27→export const RoomDetails: React.FC<
    28→  NativeStackScreenProps<Routes, "roomDetails">
    29→> = ({ navigation, route }) => {
    30→  const { room } = route.params;
    31→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
    32→  const isFocused = useIsFocused();
    33→  const isDirect = useMemo(() => roomInfo?.isDirect, [roomInfo]);
    34→  const isEncrypted = useMemo(
    35→    () => roomInfo?.encryptionState === EncryptionState.Encrypted,
    36→    [roomInfo],
    37→  );
    38→  const hasNoCallOption = useMemo(
    39→    () => (roomInfo?.isPublic && !isEncrypted) || !isEncrypted,
    40→    [roomInfo, isEncrypted],
    41→  );
    42→  const { isLeavingRoom, members, refreshMembers, leaveRoom } = useLeaveRoom(
    43→    room,
    44→    {
    45→      onSuccess: () => {
    46→        navigation.reset({
    47→          index: 0,
    48→          routes: [{ name: "home" }],
    49→        });
    50→      },
    51→    },
    52→  );
    53→  const [loading, setLoading] = useState(true);
    54→  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
    55→  const isAdmin = useMemo(() => userPowerLevel === 100, [userPowerLevel]);
    56→  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
    57→
    58→  const otherDirectMembersId = useMemo(() => {
    59→    return members.filter(
    60→      (member) => member.userId !== MatrixService.instance?.userId(),
    61→    )[0]?.userId;
    62→  }, [members]);
    63→
    64→  useEffect(() => {
    65→    if (!isFocused) return;
    66→
    67→    room
    68→      .roomInfo()
    69→      .then(setRoomInfo)
    70→      .catch(console.error)
    71→      .finally(() => {
    72→        setLoading(false);
    73→      });
    74→
    75→    MatrixService.getUserPowerLevel(room.id())
    76→      .then(setUserPowerLevel)
    77→      .catch(console.error);
    78→
    79→    refreshMembers();
    80→  }, [room, isFocused, refreshMembers]);
    81→
    82→  if (loading) return <Loading />;
    83→
    84→  return (
    85→    <ScreenLayout>
    86→      {isLeavingRoom && <Loading text="Leaving room..." />}
    87→      <Block flex={1} scrollable>
    88→        <GoBackHeader
    89→          margins={{ marginBottom: 40 }}
    90→          rightComp={
    91→            !isDirect &&
    92→            isAdmin && (
    93→              <Button.Wrapper
    94→                onPress={() =>
    95→                  navigation.navigate("editRoom", {
    96→                    room,
    97→                  })
    98→                }
    99→              >
   100→                <Text>Edit</Text>
   101→              </Button.Wrapper>
   102→            )
   103→          }
   104→        />
   105→        <Block align="center" gap={12}>
   106→          <RoomImage room={room} width={80} height={80} />
   107→          <Text size={TextSize.medium} font="InstrumentSans-Bold">
   108→            {room.displayName()}
   109→          </Text>
   110→          {isDirect && roomInfo?.heroes[0]?.userId && (
   111→            <Text color={Colors.white50}>{roomInfo?.heroes[0]?.userId}</Text>
   112→          )}
   113→          <EncryptionStatus roomInfo={roomInfo} />
   114→        </Block>
   115→        <ActionButtons
   116→          isDirect={!!isDirect}
   117→          room={room}
   118→          members={members}
   119→          hasNoCallOption={hasNoCallOption}
   120→        />
   121→        <Topic room={room} topic={roomInfo?.topic} isAdmin={isAdmin} />
   122→        <Block
   123→          border={{ borderRadius: 16 }}
   124→          width="100%"
   125→          background={Colors.white5}
   126→          margins={{ marginBottom: 20 }}
   127→        >
   128→          <SettingsListItem
   129→            title="Notifications"
   130→            icon={require("assets/icons/bell.png")}
   131→            showSeparator
   132→            onPress={() => navigation.navigate("roomNotifications")}
   133→          />
   134→          {isDirect ? (
   135→            <Button.Wrapper
   136→              onPress={() =>
   137→                navigation.navigate("profile", {
   138→                  userId: otherDirectMembersId,
   139→                })
   140→              }
   141→            >
   142→              <Block paddings={[0, 12]}>
   143→                <Block
   144→                  flexDirection="row"
   145→                  align="center"
   146→                  gap={12}
   147→                  paddings={[20, 0]}
   148→                  border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
   149→                >
   150→                  <Image
   151→                    source={require("assets/icons/user.png")}
   152→                    tintColor={Colors.white50}
   153→                    width={24}
   154→                    height={24}
   155→                  />
   156→                  <Text>View profile</Text>
   157→                  <Block
   158→                    margins={{ marginLeft: "auto" }}
   159→                    flexDirection="row"
   160→                    align="center"
   161→                    gap={8}
   162→                  >
   163→                    <Image
   164→                      source={require("assets/icons/caret-left.png")}
   165→                      style={styles.caret}
   166→                      tintColor={Colors.white50}
   167→                    />
   168→                  </Block>
   169→                </Block>
   170→              </Block>
   171→            </Button.Wrapper>
   172→          ) : (
   173→            <Button.Wrapper
   174→              onPress={() =>
   175→                navigation.navigate("roomMembers", {
   176→                  members,
   177→                  roomId: room.id(),
   178→                })
   179→              }
   180→            >
   181→              <Block paddings={[0, 12]}>
   182→                <Block
   183→                  flexDirection="row"
   184→                  align="center"
   185→                  gap={12}
   186→                  paddings={[20, 0]}
   187→                  border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
   188→                >
   189→                  <Image
   190→                    source={require("assets/icons/users.png")}
   191→                    tintColor={Colors.white50}
   192→                    width={24}
   193→                    height={24}
   194→                  />
   195→                  <Text>Members</Text>
   196→                  <Block
   197→                    margins={{ marginLeft: "auto" }}
   198→                    flexDirection="row"
   199→                    align="center"
   200→                    gap={8}
   201→                  >
   202→                    <Text color={Colors.white50}>
   203→                      (
   204→                      {
   205→                        members.filter(
   206→                          (member) =>
   207→                            member.membership?.tag ===
   208→                            MembershipState_Tags.Join,
   209→                        ).length
   210→                      }
   211→                      )
   212→                    </Text>
   213→                    <Image
   214→                      source={require("assets/icons/caret-left.png")}
   215→                      style={styles.caret}
   216→                      tintColor={Colors.white50}
   217→                    />
   218→                  </Block>
   219→                </Block>
   220→              </Block>
   221→            </Button.Wrapper>
   222→          )}
   223→          <SettingsListItem
   224→            title="Media and files"
   225→            icon={require("assets/icons/camera.png")}
   226→            onPress={() => navigation.navigate("roomMedia", { room })}
   227→            showSeparator={!!pinnedEventIds.length}
   228→          />
   229→          {!!pinnedEventIds.length && (
   230→            <SettingsListItem
   231→              title="Pinned events"
   232→              icon={require("assets/icons/pin.png")}
   233→              onPress={() => navigation.navigate("pinnedEvents", { room })}
   234→            />
   235→          )}
   236→        </Block>
   237→        <LeaveRoom onPress={leaveRoom} />
   238→      </Block>
   239→    </ScreenLayout>
   240→  );
   241→};
   242→
   243→const styles = StyleSheet.create({
   244→  caret: {
   245→    transform: [{ rotate: "180deg" }],
   246→    width: 24,
   247→    height: 24,
   248→    marginLeft: "auto",
   249→  },
   250→});
   251→

