     6→import { useCallback, useEffect, useState } from "react";
     7→import { Alert } from "react-native";
     8→import Toast from "react-native-toast-message";
     9→
    10→enum LeaveRoomText {
    11→  NOT_PUBLIC = `Are you sure that you want to leave this room? This room is not public and you won't be able to rejoin without an invite.`,
    12→  EMPTY_ROOM = "Are you sure that you want to leave this room? You're the only person here. If you leave, no one will be able to join in the future, including you.",
    13→  PUBLIC = "Are you sure that you want to leave the room?",
    14→}
    15→
    16→interface UseLeaveRoomOptions {
    17→  onSuccess?: () => void;
    18→}
    19→
    20→export const useLeaveRoom = (
    21→  room: RoomInterface,
    22→  options?: UseLeaveRoomOptions,
    23→) => {
    24→  const [isLeavingRoom, setIsLeavingRoom] = useState(false);
    25→  const [members, setMembers] = useState<RoomMember[]>([]);
    26→  const [isRefreshingMembers, setIsRefreshingMembers] = useState(false);
    27→
    28→  const refreshMembers = useCallback(async () => {
    29→    setIsRefreshingMembers(true);
    30→    try {
    31→      const membersInfo = await room.members();
    32→      const membersList = membersInfo.nextChunk(1000) ?? [];
    33→      setMembers(membersList);
    34→    } catch (error) {
    35→      console.error("Failed to refresh members:", error);
    36→    } finally {
    37→      setIsRefreshingMembers(false);
    38→    }
    39→  }, [room]);
    40→
    41→  useEffect(() => {
    42→    refreshMembers();
    43→  }, [refreshMembers]);
    44→
    45→  const confirmLeaveRoom = useCallback(async () => {
    46→    try {
    47→      setIsLeavingRoom(true);
    48→      await MatrixService.leaveRoom(room.id());
    49→      Toast.show({
    50→        type: "success",
    51→        text1: "Room left successfully",
    52→      });
    53→      options?.onSuccess?.();
    54→    } catch (error) {
    55→      console.error(error);
    56→      Toast.show({
    57→        type: "error",
    58→        text1: "Failed to leave room",
    59→      });
    60→    } finally {
    61→      setIsLeavingRoom(false);
    62→    }
    63→  }, [room, options]);
    64→
    65→  const leaveRoom = useCallback(() => {
    66→    const isEmptyRoom = Number(members.length) === 1;
    67→
    68→    const textRoom = isEmptyRoom
    69→      ? LeaveRoomText.EMPTY_ROOM
    70→      : room.isPublic()
    71→        ? LeaveRoomText.PUBLIC
    72→        : LeaveRoomText.NOT_PUBLIC;
    73→
    74→    Alert.alert("Leave Room", textRoom, [
    75→      { text: "Cancel", style: "cancel" },
    76→      { text: "Leave", onPress: confirmLeaveRoom },
    77→    ]);
    78→  }, [members, room, confirmLeaveRoom]);
    79→
    80→  return {
    81→    leaveRoom,
    82→    isLeavingRoom,
    83→    members,
    84→    refreshMembers,
    85→    isRefreshingMembers,
    86→  };
    87→};
